from pathlib import Path
import json
R=Path(__file__).resolve().parent
def read(p):return json.loads(p.read_text(encoding='utf8'))
def js(x):return json.dumps(x,ensure_ascii=False).replace('</','<\\/').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
rows=read(R/'evidence/pilot/all900_response_inventory.json')
index=read(R/'all900_index.json')
reviews=read(R/'semantic_review.json')
annotations={(r['id'],r['model']):r for r in reviews['annotations']}
images=read(R/'evidence/pilot/image_manifest.json')
(R/'explorer_data').mkdir(exist_ok=True)
for i,row in enumerate(rows):
    base=row['models']['baseline']['record']
    item={'id':row['id'],'subject':row['subject'],'question':base['question'],'options':base['options'],'gold':base['reference_answer'],'prompt':base['input_prompt'],
      'images':['evidence/'+x['path'] for x in images if x['id']==row['id']], 'models':{}}
    index[i]['reviewed']=bool(item['images'])
    for m,x in row['models'].items():
        item['models'][m]={'raw':x['record']['model_response']['raw'],'grading':x['record']['grading']['final'],**index[i]['models'][m],
          'semantic':annotations.get((row['id'],m)),'repetition':x['repetition']}
    (R/'explorer_data'/f'{row["id"]}.js').write_text('window.showItem('+js(item)+');',encoding='utf8')
(R/'explorer_index.js').write_text('const ITEMS='+js(index)+';',encoding='utf8')
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ERA MMMU 900 · seed 3407</title><style>
*{box-sizing:border-box}body{margin:0;background:#f5f6f8;color:#202b37;font:15px/1.55 system-ui,sans-serif}header{background:#142838;color:white;padding:25px 32px}h1{margin:0;font-size:25px}header p{margin:7px 0 0;color:#d1dde7}.filters{padding:16px 25px;display:flex;gap:12px;flex-wrap:wrap;background:white;border-bottom:1px solid #d6dce0;position:sticky;top:0;z-index:2}label{font-size:12px;color:#536270}select,input{display:block;padding:8px;border:1px solid #b6c4cd;border-radius:5px;max-width:280px}main{display:grid;grid-template-columns:285px 1fr;gap:22px;padding:22px}aside{height:78vh;overflow:auto;background:white;border-radius:8px}#count{padding:12px;color:#526573}#list button{display:block;text-align:left;width:100%;border:0;border-top:1px solid #e4e9ec;background:white;padding:11px 14px;color:#22323f;cursor:pointer}#list button.active{background:#dcecf7;border-left:4px solid #3277a5}#list small{display:block;color:#6b7680}h2{font-size:20px}#question{white-space:pre-wrap}.panel{background:white;padding:18px;border:1px solid #dfe5e9;border-radius:8px;margin-bottom:18px}.images{display:flex;gap:15px;flex-wrap:wrap}.images img{max-width:min(100%,650px);max-height:550px;object-fit:contain}.cards{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{min-width:0;background:white;border:1px solid #dbe3e8;border-radius:8px;padding:18px}.card h3{margin:0 0 8px}.good{color:#197152}.bad{color:#b63c37}.badge{padding:2px 7px;border-radius:4px;background:#eaf0f4;margin-right:5px;font-size:12px;display:inline-block}.response{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.65 ui-monospace,Consolas,monospace;max-height:620px;overflow:auto;border-top:1px solid #e5e9ec;padding-top:12px}.note{font-size:13px;background:#fff8e8;padding:10px;margin-top:12px;white-space:pre-wrap}details{margin-top:10px}summary{cursor:pointer;color:#285e83}.muted{color:#65737f;font-size:13px}button{cursor:pointer}a{color:#17638e}@media(max-width:1050px){main{grid-template-columns:220px 1fr}.cards{grid-template-columns:1fr}}@media(max-width:700px){main{display:block}aside{height:230px;margin-bottom:15px}.filters{position:static}header{padding:18px}}
</style><header><h1>ERA · MMMU 900문항 비교</h1><p>Baseline / 2 / 3 / 4 epoch · 동일 seed 3407 · 반복 실행은 집계에서 제외</p><p>정답률: 63.89% → 57.11% / 56.56% / 55.89% · 형식 검사는 내용 정확성 검사가 아닙니다.</p></header>
<div class="filters"><label>문항 ID / 분야 검색<input id="search" placeholder="Physics, validation_Math_24"></label><label>분야<select id="subject"><option value="">전체 분야</option></select></label><label>비교 모델<select id="model"><option value="epoch_2">2 epoch</option><option value="epoch_3">3 epoch</option><option value="epoch_4">4 epoch</option><option value="baseline">Baseline</option></select></label><label>필터<select id="filter"><option value="all">전체</option><option value="regress">Baseline 정답 → 오답</option><option value="improve">Baseline 오답 → 정답</option><option value="wrong">오답</option><option value="formatfail">ERA 형식 실패</option><option value="formatwrong">ERA 완성 + 오답</option><option value="length">길이 상한 도달</option><option value="repeat">동일 줄 3회 이상</option><option value="review">내용 검토 30문항</option></select></label><label>정렬<select id="sort"><option value="id">문항 순서</option><option value="tokens">출력 토큰 많은 순</option></select></label></div>
<main><aside><div id="count"></div><div id="list"></div></aside><section><div class="panel"><h2 id="title">문항을 선택하세요</h2><p id="question"></p><pre id="options"></pre><b id="gold"></b><div id="images" class="images"></div><p id="imageNote" class="muted"></p><details><summary>동일 입력 프롬프트</summary><pre id="prompt" class="response"></pre></details></div><div id="cards" class="cards"></div><p class="muted">전체 900문항: 자동 지표 및 원문 제공. 직접 내용 검토: 사전 선정30문항의120응답(긴12응답은 발췌). Assistant 정성검토이며 사람 독립검수가 아닙니다. 0=핵심 오류/설명 부재, 1=부분 정확, 2=충분 정확, ?=미확정. 공식 채점은 보존했습니다.</p><a href="report.md">한국어 보고서</a> · <a href="semantic_review.json">내용 검토 근거 JSON</a> · <a href="local_verification.json">로컬 검증 기록</a></section></main>
<script src="explorer_index.js"></script><script>
const $=s=>document.getElementById(s);let selected='';const labels={baseline:'Baseline',epoch_2:'2 epoch',epoch_3:'3 epoch',epoch_4:'4 epoch'};
for(const s of [...new Set(ITEMS.map(x=>x.subject))]){let o=document.createElement('option');o.value=o.textContent=s;$('subject').append(o)}
function allowed(x){let m=x.models[$('model').value],b=x.models.baseline;switch($('filter').value){case'regress':return b.correct&&!m.correct;case'improve':return !b.correct&&m.correct;case'wrong':return !m.correct;case'formatfail':return !m.format;case'formatwrong':return m.format&&!m.correct;case'length':return m.length;case'repeat':return m.repeat;case'review':return x.reviewed;default:return true}}
function refresh(){let query=$('search').value.toLowerCase();let rows=ITEMS.filter(x=>(!$('subject').value||x.subject===$('subject').value)&&x.id.toLowerCase().includes(query)&&allowed(x));if($('sort').value==='tokens')rows.sort((a,b)=>b.models[$('model').value].tokens-a.models[$('model').value].tokens);$('count').textContent=`${rows.length} / 900문항`;$('list').replaceChildren();for(const x of rows){let b=document.createElement('button');b.dataset.id=x.id;b.className=x.id===selected?'active':'';b.append(document.createTextNode(x.id.replace('validation_','')));let s=document.createElement('small');s.textContent=Object.keys(labels).map(m=>labels[m]+': '+(x.models[m].correct?'O':'X')).join(' · ');b.append(s);b.onclick=()=>choose(x.id);$('list').append(b)}}
function choose(id){selected=id;location.hash=id;$('title').textContent='불러오는 중…';let script=document.createElement('script');script.src='explorer_data/'+id+'.js';script.onload=()=>script.remove();script.onerror=()=>{$('title').textContent='파일을 불러올 수 없습니다. explorer_data 폴더를 함께 보관하세요.';script.remove()};document.body.append(script);refresh()}
window.showItem=x=>{if(x.id!==selected)return;$('title').textContent=x.id;$('question').textContent=x.question;$('options').textContent=Object.entries(x.options||{}).map(([k,v])=>k+'. '+v).join('\n');$('gold').textContent='공식 정답: '+x.gold;$('prompt').textContent=x.prompt;$('images').replaceChildren();for(const url of x.images){let a=document.createElement('a');a.href=url;a.target='_blank';let im=document.createElement('img');im.src=url;im.alt=x.id+' 원본 이미지';a.append(im);$('images').append(a)}$('imageNote').textContent=x.images.length?'사전 선정 검토 문항의 원본 이미지 · 클릭하면 원본 크기로 열립니다.':'이 문항의 원본 이미지는 이 탐색 자료에 회수하지 않았습니다. 내용 정확성은 미검토입니다.';$('cards').replaceChildren();for(const [m,v]of Object.entries(x.models)){let c=document.createElement('article');c.className='card';let h=document.createElement('h3');h.textContent=labels[m]+' · '+(v.correct?'정답':'오답');h.className=v.correct?'good':'bad';c.append(h);let meta=document.createElement('p');meta.textContent=`채점 답: ${v.answer} · ${v.tokens.toLocaleString()} tokens`;c.append(meta);for(const t of [(v.format?'ERA 완성':'ERA 미완성'),(v.legacy?'표제 있음':'표제 없음'),...(v.length?['길이 상한']:[]),...(v.repeat?['동일 줄 반복']:[])]){let b=document.createElement('span');b.className='badge';b.textContent=t;c.append(b)}if(v.semantic){let n=document.createElement('div');n.className='note';let a=v.semantic;n.textContent='E/R/A: '+['E','R','A'].map(k=>a.scores[k]??'?').join('/')+' · '+(a.coverage==='full_response'?'응답 전체 검토':'긴 응답 발췌 검토')+'\n'+a.rationale;c.append(n)}else{let n=document.createElement('p');n.className='muted';n.textContent='E/R/A 내용 정확성 미검토';c.append(n)}let raw=document.createElement('pre');raw.className='response';raw.textContent=v.raw;c.append(raw);let d=document.createElement('details'),s=document.createElement('summary'),p=document.createElement('pre');s.textContent='공식 채점 기록';p.className='response';p.textContent=JSON.stringify(v.grading,null,2);d.append(s,p);c.append(d);$('cards').append(c)}};
for(const id of ['search','subject','model','filter','sort'])$(id).addEventListener('input',refresh);refresh();const wanted=decodeURIComponent(location.hash.slice(1));choose(ITEMS.some(x=>x.id===wanted)?wanted:ITEMS[0].id);
</script></html>'''
# Backslash escapes in JavaScript must survive Python literal parsing.
html=html.replace("join('\n')", "join('\\n')").replace("+'\n'+a.rationale", "+'\\n'+a.rationale")
(R/'explorer.html').write_text(html,encoding='utf8')
print('Explorer created:',len(rows),'items')
